@import "@fontsource-variable/inter";
@import "@fontsource-variable/manrope";
@import "@fontsource-variable/source-code-pro";

/* Light (faithful): a #fdfdfd page with pure white cards, near-black ink (oklch 0.1) for
   headings and stressed words, mid grey (oklch 0.52) for the rest, ink-at-8% hairlines.
   One brand green: deep (#0f7e4f) for buttons and the hero's second line, bright mint
   (#3ecf8e) for the mark and lit dots. Charts double as code syntax (purple keywords, deep
   green names, amber strings) and the story card's pink→orange gradient (chart-4 → 5). */
:root {
  --background: oklch(0.995 0 0);
  --foreground: oklch(0.1 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.1 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.1 0 0);
  --primary: oklch(0.525 0.12 157.5);
  --primary-foreground: oklch(0.99 0.00275 157.5);
  --secondary: oklch(0.97 0 0);
  --secondary-foreground: oklch(0.1 0 0);
  --muted: oklch(0.97 0 0);
  --muted-foreground: oklch(0.52 0 0);
  --accent: oklch(0.96 0 0);
  --accent-foreground: oklch(0.1 0 0);
  --destructive: oklch(0.58 0.2 27);
  --destructive-foreground: oklch(0.99 0 0);
  --border: oklch(0.1 0 0 / 8%);
  --input: oklch(0.1 0 0 / 15%);
  --ring: oklch(0.525 0.12 157.5);
  --highlight: oklch(0.77 0.15 162);
  --highlight-foreground: oklch(0.1 0 0);
  --glow: oklch(0.45 0.2 268);
  --chart-1: oklch(0.5 0.22 290);
  --chart-2: oklch(0.42 0.08 160);
  --chart-3: oklch(0.55 0.15 50);
  --chart-4: oklch(0.63 0.25 5);
  --chart-5: oklch(0.75 0.18 55);
  --sidebar: oklch(0.995 0 0);
  --sidebar-foreground: oklch(0.1 0 0);
  --sidebar-primary: oklch(0.525 0.12 157.5);
  --sidebar-primary-foreground: oklch(0.99 0.00275 157.5);
  --sidebar-accent: oklch(0.96 0 0);
  --sidebar-accent-foreground: oklch(0.1 0 0);
  --sidebar-border: oklch(0.1 0 0 / 8%);
  --sidebar-ring: oklch(0.525 0.12 157.5);

  --typeface-body: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Manrope Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Source Code Pro Variable", ui-monospace, SFMono-Regular, Menlo, monospace;
  --radius: 0.5rem;
  --page-width: 68rem;
  --page-gutter: 1.5rem;
  --section-y: 4rem;
}

/* Dark sibling, also used by the dark brand strips on the light page: a #121212 ground,
   #171717 cards, #ededed ink, #a0a0a0 grey, the green lifted so buttons stay readable. The
   story gradient (chart-4, chart-5) stays the same in both modes. */
.dark {
  --background: oklch(0.18 0 0);
  --foreground: oklch(0.94 0 0);
  --card: oklch(0.205 0 0);
  --card-foreground: oklch(0.94 0 0);
  --popover: oklch(0.205 0 0);
  --popover-foreground: oklch(0.94 0 0);
  --primary: oklch(0.47 0.11 157.5);
  --primary-foreground: oklch(0.99 0.00275 157.5);
  --secondary: oklch(0.24 0.04 220);
  --secondary-foreground: oklch(0.94 0 0);
  --muted: oklch(0.25 0 0);
  --muted-foreground: oklch(0.7 0 0);
  --accent: oklch(0.27 0 0);
  --accent-foreground: oklch(0.94 0 0);
  --destructive: oklch(0.65 0.2 25);
  --destructive-foreground: oklch(0.99 0 0);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 16%);
  --ring: oklch(0.77 0.15 162);
  --highlight: oklch(0.77 0.15 162);
  --highlight-foreground: oklch(0.18 0 0);
  --glow: oklch(0.45 0.2 268);
  --chart-1: oklch(0.72 0.16 295);
  --chart-2: oklch(0.8 0.12 162);
  --chart-3: oklch(0.78 0.13 65);
  --chart-4: oklch(0.63 0.25 5);
  --chart-5: oklch(0.75 0.18 55);
  --sidebar: oklch(0.18 0 0);
  --sidebar-foreground: oklch(0.94 0 0);
  --sidebar-primary: oklch(0.47 0.11 157.5);
  --sidebar-primary-foreground: oklch(0.99 0.00275 157.5);
  --sidebar-accent: oklch(0.27 0 0);
  --sidebar-accent-foreground: oklch(0.94 0 0);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.77 0.15 162);
}
